#include "dsky_decimal_raw_check.h"
#include "dsky_decimal_raw_vectors.h"
uint8_t dsky_decimal_raw_checkpoint_input(uint8_t n,apollo_overlay_state *s,p66_bias_io *io,enum dsky_nv_mission *mission,uint8_t *rounded){if(n>=128u)return 0;dsky_decimal_raw_input(s,io,dsky_decimal_raw_numbers[n],mission,rounded);return 1;}
uint16_t dsky_decimal_raw_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;uint8_t rounded;enum dsky_decimal_general_route route=(enum dsky_decimal_general_route)2;uint16_t f,p,end,failures=0;if(!dsky_decimal_raw_checkpoint_input(n,s,&io,&mission,&rounded))return 1;*before=*s;old=io;if(dsky_decimal_raw(s,&io,mission,rounded,&route)!=P66_BIAS_OK)++failures;p=dsky_decimal_raw_after_offsets[n];end=dsky_decimal_raw_after_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:2;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:(uint16_t)route;if(p<end&&dsky_decimal_raw_after_patch[p][0]==f)expected=dsky_decimal_raw_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
